import unittest


class TestBelowZero(unittest.TestCase):

    def test_never_below_zero(self):
        self.assertFalse(below_zero([1, 2, 3]))

    def test_goes_below_zero(self):
        self.assertTrue(below_zero([1, 2, -4, 5]))

    def test_empty_list(self):
        self.assertFalse(below_zero([]))

    def test_exactly_zero(self):
        # Balance reaching zero is not below zero
        self.assertFalse(below_zero([1, -1]))

    def test_single_negative(self):
        self.assertTrue(below_zero([-1]))

    def test_single_positive(self):
        self.assertFalse(below_zero([1]))

    def test_dips_below_then_recovers(self):
        self.assertTrue(below_zero([10, -15, 20]))

    def test_all_positive(self):
        self.assertFalse(below_zero([1, 2, 3, 4, 5]))

    def test_all_negative(self):
        self.assertTrue(below_zero([-1, -2, -3]))

    def test_stays_at_zero_then_negative(self):
        self.assertTrue(below_zero([5, -5, -1]))

    def test_large_numbers(self):
        self.assertFalse(below_zero([1000000, -999999]))
        self.assertTrue(below_zero([1000000, -1000001]))

    def test_alternating(self):
        self.assertFalse(below_zero([2, -1, 2, -1, 2, -1]))


if __name__ == "__main__":
    unittest.main()
